BEGIN;
SELECT plan(58);

-- Each sensitive table must keep RLS enabled, expose an owner/admin-only SELECT policy,
-- and contain no permissive authenticated/public policy for any CRUD command.

SELECT ok((SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = 'public.people_employees'::regclass), 'people_employees: RLS remains enabled');
SELECT ok(EXISTS (SELECT 1 FROM pg_policies p WHERE p.schemaname='public' AND p.tablename='people_employees' AND p.policyname='people_sensitive_select_admin' AND p.cmd='SELECT' AND 'authenticated'=ANY(p.roles) AND p.qual ILIKE '%has_business_role%' AND p.qual ILIKE '%owner%' AND p.qual ILIKE '%admin%'), 'people_employees: SELECT is owner/admin-only');
SELECT ok(NOT EXISTS (SELECT 1 FROM pg_policies p WHERE p.schemaname='public' AND p.tablename='people_employees' AND p.cmd IN ('SELECT','INSERT','UPDATE','DELETE','ALL') AND (NOT ('authenticated'=ANY(p.roles)) OR concat_ws(' ',p.qual,p.with_check) NOT ILIKE '%has_business_role%' OR concat_ws(' ',p.qual,p.with_check) NOT ILIKE '%owner%' OR concat_ws(' ',p.qual,p.with_check) NOT ILIKE '%admin%')), 'people_employees: no broad member/public CRUD policy remains');

